/**
 * SimulationEngine — choreographs one infiltration run.
 *
 * The whole sequence is compiled to a flat script of timed steps before
 * playback begins. That makes pause/resume trivial (stop advancing the
 * cursor), makes replay exact (same seed ⇒ same script), and keeps the
 * hot loop free of branching logic.
 *
 * Nothing here executes anything. Every "command" in the output is a
 * decorative string generated by MockDataGenerator.
 */

import { makeRng, fillerLine, generateDataset } from './MockDataGenerator.js';

export const SPEEDS = {
	slow: { label: 'SLOW', mult: 1.75 },
	normal: { label: 'NORMAL', mult: 1 },
	fast: { label: 'FAST', mult: 0.5 },
	cinematic: { label: 'CINEMATIC', mult: 2.3 }
};

export const STAGES = [
	{ id: 'handshake', label: 'HANDSHAKE', n: 1 },
	{ id: 'sweep', label: 'SURFACE SWEEP', n: 2 },
	{ id: 'extract', label: 'EXTRACTION', n: 3 },
	{ id: 'assemble', label: 'ASSEMBLY', n: 4 },
	{ id: 'complete', label: 'COMPLETE', n: 5 }
];

let lineSeq = 0;

export class SimulationEngine {
	/**
	 * @param {object} opts
	 * @param {string} opts.moduleId
	 * @param {object} opts.facility
	 * @param {number} opts.seed
	 * @param {keyof SPEEDS} opts.speed
	 * @param {object} opts.on  callbacks: lines, stage, progress, sfx, done
	 */
	constructor({ moduleId, facility, seed, speed = 'normal', on = {} }) {
		this.moduleId = moduleId;
		this.facility = facility;
		this.seed = seed;
		this.speed = speed;
		this.on = on;

		this.script = [];
		this.cursor = 0;
		this.state = 'idle'; // idle | running | paused | done | aborted
		this.progress = 0;

		this._timer = null;
		this._pendingDelay = 0;
		this._pausedAt = 0;
		this._stepStartedAt = 0;

		this.dataset = generateDataset(moduleId, facility, seed);
		this._compile();
	}

	get mult() {
		return SPEEDS[this.speed]?.mult ?? 1;
	}

	setSpeed(speed) {
		this.speed = speed;
	}

	/* ------------------------------------------------------------------
	   Script compilation
	   ------------------------------------------------------------------ */

	_compile() {
		const rng = makeRng(this.seed ^ 0x9e3779b9);
		const f = this.facility;
		const mod = this.dataset.module;
		const S = [];

		const line = (level, text, opts = {}) =>
			S.push({ t: 'line', level, text, delay: opts.d ?? 70, typed: opts.typed ?? false, hl: opts.hl ?? false });
		const wait = (d) => S.push({ t: 'wait', delay: d });
		const stage = (id) => S.push({ t: 'stage', stage: id, delay: 0 });
		const prog = (to, d = 0) => S.push({ t: 'progress', to, delay: d });
		const sfx = (name, d = 0) => S.push({ t: 'sfx', name, delay: d });

		/* ---------- STAGE 1 — HANDSHAKE ---------- */
		stage('handshake');
		sfx('startup');
		line('sys', '[SYS] CYBERX SIMULATION ENGINE — BUILD 4.17.2', { d: 180, typed: true });
		line('dim', '[SYS] all output below is synthetic. no live system is contacted.', { d: 120, typed: true });
		line('sys', `[SYS] TARGET ACQUIRED :: ${f.name}`, { d: 160, typed: true });
		line('info', `[LOG] operator ......... ${f.operator}`, { d: 90 });
		line('info', `[LOG] designation ...... ${f.designation}`, { d: 90 });
		line('info', `[LOG] sector ........... ${f.sector}`, { d: 90 });
		line('info', `[LOG] hardening ........ ${f.hardening}/100 (${f.tier})`, { d: 110 });
		line('sys', `[SYS] MODULE SELECTED :: ${mod.title}`, { d: 200, typed: true, hl: true });
		prog(4);
		line('ok', '[ OK ] virtual session established', { d: 160 });
		sfx('beep');
		wait(260);

		/* ---------- STAGE 2 — SURFACE SWEEP ---------- */
		stage('sweep');
		sfx('scan');
		line('sys', '[SYS] INITIATING SURFACE SWEEP…', { d: 140, typed: true });
		line('dim', `[LOG] probing ${rng.int(640, 4096)} apertures across ${rng.int(4, 19)} segments`, { d: 110 });
		wait(180);

		// Bursts of decorative traffic, interleaved with pauses — this is the
		// rhythm that makes the sequence feel like a machine thinking.
		//
		// Lines inside a sub-group carry delay 0 so the engine coalesces them
		// into one UI update; the `wait` between sub-groups is what creates
		// the visible stutter-and-rush cadence.
		const sweepBursts = 11;
		for (let b = 0; b < sweepBursts; b++) {
			const groups = rng.int(2, 4);
			for (let g = 0; g < groups; g++) {
				const count = rng.int(3, 7);
				for (let i = 0; i < count; i++) {
					const fl = fillerLine(rng, 'scan');
					S.push({ t: 'line', level: fl.level, text: fl.text, delay: 0, typed: false, quiet: i !== 0 });
				}
				wait(rng.int(26, 64));
			}
			prog(4 + Math.round(((b + 1) / sweepBursts) * 48));

			if (b === 3) {
				sfx('glitch');
				line('err', `[FAIL] segment ${rng.hex(4)} dropped mid-read — compensating`, { d: 160, hl: true });
			}
			if (b === 6) {
				sfx('warning');
				line('warn', `[WARN] counter-intrusion heuristic engaged at depth ${rng.int(2, 7)}`, { d: 170, hl: true });
				line('dim', '[LOG] masking signature, backing off 400ms', { d: 120 });
			}
			if (b === 8) {
				sfx('scan');
				line('info', `[I/O] deep lattice responded · ${rng.int(120, 980)} nodes visible`, { d: 140 });
			}
			wait(rng.int(90, 340));
		}
		line('ok', '[ OK ] surface sweep complete — topology mapped', { d: 180, hl: true });
		sfx('beep');
		prog(54);
		wait(240);

		/* ---------- STAGE 3 — EXTRACTION ---------- */
		stage('extract');
		sfx('processStart');
		line('sys', '[SYS] ENTERING EXTRACTION PHASE', { d: 170, typed: true });
		line('log', '[LOG] GENERATING SYNTHETIC ACTIVITY RECORDS…', { d: 150, typed: true });

		const recordCount = this.dataset.records.length;
		for (let i = 0; i < recordCount; i++) {
			const r = this.dataset.records[i];
			const ref = r.id ?? `REC-${i}`;
			S.push({
				t: 'line',
				level: r.flagged ? 'warn' : 'ok',
				text: `[REC] ${String(i + 1).padStart(3, '0')}/${recordCount}  ${ref}  ${r.flagged ? '⚑ anomaly' : 'nominal'}  ${'▮'.repeat(rng.int(2, 9))}`,
				delay: rng.int(45, 130),
				quiet: i % 2 === 1
			});
			if (i % 3 === 2) {
				for (let k = 0; k < rng.int(2, 4); k++) {
					const fl = fillerLine(rng, 'extract');
					S.push({ t: 'line', level: fl.level, text: fl.text, delay: 0, quiet: true });
				}
				wait(rng.int(18, 46));
			}
			prog(54 + Math.round(((i + 1) / recordCount) * 30));
		}

		line('log', '[LOG] PROCESSING SYNTHETIC TIMESTAMPS…', { d: 160 });
		for (let g = 0; g < 5; g++) {
			for (let i = 0; i < rng.int(2, 5); i++) {
				const fl = fillerLine(rng, 'extract');
				S.push({ t: 'line', level: fl.level, text: fl.text, delay: 0, quiet: i !== 0 });
			}
			wait(rng.int(30, 70));
		}
		prog(86);
		sfx('processStop');
		wait(220);

		/* ---------- STAGE 4 — ASSEMBLY ---------- */
		stage('assemble');
		line('sys', '[SYS] BUILDING ACTIVITY TIMELINE…', { d: 170, typed: true });
		line('info', `[LOG] correlating ${recordCount} records against ${rng.int(3, 11)} reference frames`, { d: 140 });
		for (let i = 0; i < 9; i++) {
			const fl = fillerLine(rng, 'assemble');
			S.push({ t: 'line', level: fl.level, text: fl.text, delay: rng.int(28, 72), quiet: true });
		}
		line('log', '[LOG] RENDERING SAMPLE DATA…', { d: 150 });
		for (let i = 0; i < 5; i++) {
			const fl = fillerLine(rng, 'assemble');
			S.push({ t: 'line', level: fl.level, text: fl.text, delay: 0, quiet: i !== 0 });
		}
		prog(93);
		line('info', `[LOG] coverage ${this.dataset.integrity.coverage}% · confidence ${this.dataset.integrity.confidence}%`, { d: 150 });
		line('log', '[LOG] PREPARING DEMONSTRATION REPORT…', { d: 160 });
		prog(99);
		wait(300);

		/* ---------- STAGE 5 — COMPLETE ---------- */
		stage('complete');
		prog(100);
		sfx('complete');
		line('ok', '', { d: 60 });
		line('ok', '  ╔══════════════════════════════════════════╗', { d: 55 });
		line('ok', '  ║        S I M U L A T I O N   D O N E      ║', { d: 55, hl: true });
		line('ok', '  ╚══════════════════════════════════════════╝', { d: 55 });
		line('sys', `[SYS] SYNTHETIC DATA GENERATED — ${recordCount} RECORDS`, { d: 150, typed: true });
		line('sys', `[SYS] SESSION ${this.dataset.sessionId}`, { d: 130 });
		line('warn', '[SYS] REPORT READY — CONTENTS ARE FICTIONAL', { d: 180, typed: true, hl: true });
		wait(420);

		this.script = S;
	}

	/* ------------------------------------------------------------------
	   Playback
	   ------------------------------------------------------------------ */

	play() {
		if (this.state === 'running') return;
		if (this.state === 'done' || this.state === 'aborted') return;
		this.state = 'running';
		this._advance();
	}

	pause() {
		if (this.state !== 'running') return;
		this.state = 'paused';
		clearTimeout(this._timer);
		// Preserve whatever slice of the current delay is left.
		const elapsed = performance.now() - this._stepStartedAt;
		this._pendingDelay = Math.max(0, this._pendingDelay - elapsed);
	}

	resume() {
		if (this.state !== 'paused') return;
		this.state = 'running';
		this._schedule(this._pendingDelay);
	}

	toggle() {
		if (this.state === 'running') this.pause();
		else if (this.state === 'paused') this.resume();
	}

	abort() {
		this.state = 'aborted';
		clearTimeout(this._timer);
		this.on.sfx?.('processStop');
	}

	/** Jump straight to the finished state, skipping remaining animation. */
	skipToEnd() {
		if (this.state === 'done') return;
		clearTimeout(this._timer);

		// Flush every remaining line in one batch so the log is complete.
		const rest = [];
		for (let i = this.cursor; i < this.script.length; i++) {
			const s = this.script[i];
			if (s.t === 'line') rest.push(this._mkLine(s));
			else if (s.t === 'stage') this.on.stage?.(s.stage);
		}
		if (rest.length) this.on.lines?.(rest);
		this.cursor = this.script.length;
		this.progress = 100;
		this.on.progress?.(100);
		this.on.sfx?.('processStop');
		this.state = 'done';
		this.on.done?.(this.dataset);
	}

	_mkLine(s) {
		return {
			id: ++lineSeq,
			level: s.level,
			text: s.text,
			typed: s.typed,
			hl: s.hl
		};
	}

	_schedule(ms) {
		this._pendingDelay = ms;
		this._stepStartedAt = performance.now();
		this._timer = setTimeout(() => this._advance(), ms);
	}

	_advance() {
		if (this.state !== 'running') return;

		// Drain every zero-delay step, and coalesce consecutive fast lines
		// into a single batch so the UI performs one state update per frame.
		const batch = [];
		let keySfx = false;
		let guard = 0;
		// One keystroke sound per flushed batch, not per line — a 6-line
		// burst should read as a single rattle, not six separate clicks.
		const flush = () => {
			if (!batch.length) return;
			if (keySfx) this.on.sfx?.('key');
			this.on.lines?.(batch.slice());
			batch.length = 0;
			keySfx = false;
		};

		while (this.cursor < this.script.length && guard++ < 400) {
			const step = this.script[this.cursor];
			const delay = Math.round((step.delay ?? 0) * this.mult);

			// Anything with a real delay ends this batch (after we flush).
			if (delay > 0 && batch.length > 0) break;

			this.cursor++;

			switch (step.t) {
				case 'line': {
					batch.push(this._mkLine(step));
					if (!step.quiet) keySfx = true;
					break;
				}
				case 'stage':
					this.on.stage?.(step.stage);
					break;
				case 'progress':
					this.progress = step.to;
					this.on.progress?.(step.to);
					break;
				case 'sfx':
					this.on.sfx?.(step.name);
					break;
				case 'wait':
					break;
			}

			if (delay > 0) {
				flush();
				this._schedule(delay);
				return;
			}
		}

		flush();

		if (this.cursor >= this.script.length) {
			this.state = 'done';
			this.on.sfx?.('processStop');
			this.on.done?.(this.dataset);
			return;
		}
		this._schedule(Math.round((this.script[this.cursor].delay ?? 16) * this.mult));
	}

	destroy() {
		clearTimeout(this._timer);
		this.on = {};
		this.script = [];
	}
}
